select transaction_id, transaction_type, t1.item_id, t1.item_code, t1.item_name, t1.specification, unit_of_measure, batch_code,container_code,
warehouse_id, warehouse_code, warehouse_name, location_id, location_code, location_name, area_id, area_code, area_name, vendor_id, vendor_code, vendor_name, vendor_nick,
source_doc_type, source_doc_id, source_doc_code, source_doc_line_id, material_stock_id, transaction_flag, transaction_quantity,
transaction_date, related_transaction_id, erp_date,workorder_id,workorder_code,recpt_date, expire_date,
before_quantity,after_quantity,before_weight,after_weight,waring_value,
t1.attr1, attr2, attr3, attr4, create_by, t1.create_time, update_by, update_time,weight,total_weight,weight_unit
from wms_transaction t1 INNER JOIN (
#             SELECT MAX(transaction_id) as max_transaction_id ,item_name,item_code,specification,attr1, MAX(create_time) AS create_time
SELECT MAX(transaction_id) as max_transaction_id,item_code,attr1, MAX(create_time) AS create_time
FROM wms_transaction
GROUP BY item_code,attr1
) t2 ON  t1.item_code = t2.item_code AND t1.attr1 = t2.attr1 AND t1.create_time = t2.create_time and t1.transaction_id = t2.max_transaction_id

     and t1.transaction_type = #{transactionType}
