     and t1.vendor_name like concat('%', #{vendorName}, '%')
     and t1.vendor_nick = #{vendorNick}
     and t1.source_doc_type = #{sourceDocType}
     and t1.source_doc_id = #{sourceDocId}
     and t1.source_doc_code = #{sourceDocCode}
     and t1.source_doc_line_id = #{sourceDocLineId}
     and t1.material_stock_id = #{materialStockId}
     and t1.transaction_flag = #{transactionFlag}
     and t1.transaction_quantity = #{transactionQuantity}
     and t1.transaction_date = #{transactionDate}
     and t1.related_transaction_id = #{relatedTransactionId}
